import { clamp, dbToGain, midiToHz, seeded, TONIC_MIDI } from './harmony'
import {
  createScore,
  EVENTS,
  type Note,
  type Plan,
  type SoundContext,
  type SoundEvent,
  type Tier,
} from './score'

/**
 * The instrument: plans from score.ts rendered with Web Audio, no audio files. Works on any
 * BaseAudioContext, so the same code plays in the app and renders offline for calibration and tests.
 */

/**
 * Bus level (dB) per event that meets its EVENTS loudness target. Generated by calibrate()
 * (measure.ts); re-run it after changing a voice, a chord, an event or a target.
 */
export type PaletteId = 'rhodes' | 'felt' | 'glass'

export type Palette = {
  id: PaletteId
  voice: 'piano' | 'felt' | 'glass'
  /** Pad level, room send and low-pass, relative to Rhodes. */
  pad: number
  wet: number
  cutoff: number
}

/** Timbre only: every palette plays the same notes at the same times, so a comparison is fair. */
export const PALETTES: Record<PaletteId, Palette> = {
  rhodes: { id: 'rhodes', voice: 'piano', pad: 1, wet: 0.3, cutoff: 1 },
  felt: { id: 'felt', voice: 'felt', pad: 0.8, wet: 0.34, cutoff: 0.9 },
  glass: { id: 'glass', voice: 'glass', pad: 1.15, wet: 0.36, cutoff: 1.1 },
}

type Tone = { cutoff: number; wet: number }

